// A more universal syntax
#include <vector>
#include <atomic>

// 1. Initializing an STL container
std::vector<int> v { 1, 3, 5 };

class Widget {
private:
  // 2. In-class non-static member initialization
  int x{ 0 }; // OK
  int y = 0;  // Also OK
  // int z(0); // Error!
};

// 3. Initializing a non-copyable type
std::atomic<int> ai1 { 0 }; // OK
std::atomic<int> ai2 (0);   // Also OK
// std::atomic<int> ai3 = 0; // Error! (Tries copy-initialization)
